use vstd::prelude::*;

verus! {
    fn putmask(a: Vec<f32>, mask: Vec<bool>, values: Vec<f32>) -> (result: Vec<f32>)
        requires
            a.len() == mask.len(),
            values.len() > 0,
        ensures
            result.len() == a.len(),
            forall |i: nat| 0 <= i < a.len() ==> 
                (mask[i] ==> result[i] == values[i % values.len()]) &&
                (!mask[i] ==> result[i] == a[i]),
    {
        let mut result: Vec<f32> = vec![0.0; a.len()]; // Initialize result array
        let len_values = values.len() as nat; // Length of values array

        // Loop through each index of the input array
        for i in 0..a.len() {
            if mask[i] {
                result[i] = values[i % len_values]; // Use replacement value
            } else {
                result[i] = a[i]; // Keep original value
            }
        }
        result
    }
}
